const task = $json;
const taskId = task.id || $json.taskId || $json.clickup_task_id || null;
const TEXT_EXT = ['xlsx','docx','csv','txt'];
const TEXT_MIME = [
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'text/csv',
  'text/plain'
];
const atts = Array.isArray(task.attachments) ? task.attachments : [];
const kept = [];
let order = 0;
for (const a of atts) {
  const title = a.title || '';
  const ext = String(a.extension || title.split('.').pop() || '').toLowerCase();
  const mime = String(a.mimetype || '').toLowerCase();
  if (TEXT_EXT.includes(ext) || TEXT_MIME.includes(mime)) {
    kept.push({ json: {
      clickup_task_id: taskId,
      att_id: a.id || null,
      title: title || ('attachment.' + ext),
      ext,
      mime,
      url: a.url_w_query || a.url || '',
      order: order++
    }});
  }
}
return kept;

let meta;
try { meta = $('Filter Text Attachments').item.json; } catch (e) { meta = {}; }
if (!meta || meta.order === undefined) { meta = { order: 0, title: (meta && meta.title) || 'unknown', clickup_task_id: (meta && meta.clickup_task_id) || null }; }
const doc = ($json && $json.document) || {};
const md = doc.md_content || '';
const ok = !!md;
let err = '';
if (!ok) {
  if ($json && $json.error) { err = $json.error.message || (typeof $json.error === 'string' ? $json.error : JSON.stringify($json.error)); }
  else if ($json && $json.status && $json.status !== 'success') { err = 'docling status=' + $json.status; }
  else { err = 'no md_content'; }
}
const block = ok
  ? { type: 'text', order: meta.order, md }
  : { type: 'text', order: meta.order, md: '[BRAK: extraction_failed ' + meta.title + ']' };
return { json: {
  block,
  clickup_task_id: meta.clickup_task_id,
  title: meta.title,
  needs_alert: !ok,
  has_embedded: ok && (md.includes('<!-- image -->') || md.includes('<!-- missing-image -->')),
  err: err || ''
} };

const items = $input.all();
const blocks = items
  .map(i => i.json && i.json.block)
  .filter(Boolean)
  .sort((a, b) => (a.order || 0) - (b.order || 0));
let taskId = null;
try { taskId = $('When Called').first().json.clickup_task_id; } catch (e) {}
if (!taskId) { try { taskId = $('Form Trigger').first().json.taskId; } catch (e) {} }
if (!taskId) { const f = items.find(i => i.json && i.json.clickup_task_id); taskId = f ? f.json.clickup_task_id : null; }
return [{ json: { blocks, clickup_task_id: taskId } }];
